INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('766c3ebc-a042-4c03-ad5c-d13dea343a9c', 'c1e29643-2905-4cd3-a4ef-420f1e189952', 'AETCOM: Confidentiality, Tarasoff Duty to Warn & Medical Malpractice (The 4 Ds)', 'PUBLISHED', 1)
