VALUES ('adced3da-d590-4609-a125-8247c96d510e', '700c4544-1d13-491a-a905-aeffdb633e7f', 'AETCOM: End-of-Life Ethics, The Doctrine of Double Effect & Brain Death Criteria', 'PUBLISHED', 1)
