INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('ab51c67d-68cf-437a-afd1-8e70f94ffe11', '02552dd2-73b0-46a9-ae2c-30de39478c76', 'AETCOM: The SPIKES Protocol for Delivering Bad News & NURSE Empathy Framework', 'PUBLISHED', 1)
