VALUES ('7f680626-4e6c-4899-a746-1eb8d6a73397', '7e27e92c-e818-45e6-ac96-59d8b8c4f8b4', 'Anterior Abdominal Wall, Inguinal Canal & Peritoneal Recesses', 'PUBLISHED', 1)
