INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('289c9f62-9416-46d6-aa9b-99697f931f36', 'a04a3fd6-977e-40d1-ad5e-afb37457d5f0', 'Upper Limb Osteology, Brachial Plexus & Peripheral Nerve Palsies', 'PUBLISHED', 1)
