VALUES ('e78b4f4b-aa47-42ef-a071-09172f9e4206', '751a4043-2e49-49ab-a4db-eca3341028a1', 'Cranial Base Foramina, Cavernous Sinus & Neck Triangles', 'PUBLISHED', 1)
