VALUES ('d4844f84-5c17-47ad-a400-96f7a0f23c6d', 'b590da3a-7f2d-4ae0-ab2e-b62193cbd606', 'Microscopic Architecture, Tissue Staining & Organ Histology', 'PUBLISHED', 1)
