VALUES ('c5e623c9-5c6f-4946-afe7-4ad560756cee', 'c546d0e9-1798-4ab2-a0a8-74c4c5786bcc', 'Lower Limb Compartments, Joint Biomechanics & Gait Diagnostics', 'PUBLISHED', 1)
