VALUES ('8a37e8ad-8740-4e0b-a3eb-8c400531cb0c', 'bbca9ea0-3f3e-4809-a9f6-e9a6569f2464', 'Anesthesia: Airway Assessment (Mallampati & LEMON) & ASA Difficult Airway Algorithm (CICO)', 'PUBLISHED', 1)
