INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('97adee2b-8a81-4a9a-a095-943090db7bfb', '92581fa0-e527-4771-a4ac-a782e1ed576a', 'Local Anesthetic Systemic Toxicity (LAST): Bupivacaine Nav1.5 Blockade & 20% Lipid Emulsion Rescue', 'PUBLISHED', 1)
