INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('19e2c5fd-b8d2-4e19-a73a-544a4a2b873e', 'ae9a6df9-923c-438b-a89a-1428fefb1385', 'Neuromuscular Blockade: Succinylcholine (Phase I/II & K+ Rise), Cisatracurium (Hofmann) & Sugammadex Cyclodextrin Reversal', 'PUBLISHED', 1)
