VALUES ('62f085e2-37af-4066-ad9e-7930bd4ed08b', '85f77a19-263e-403f-a17d-da7ed7c6cc5e', 'Amino Acid Catabolism, Urea Cycle & Inborn Metabolic Errors', 'PUBLISHED', 1)
