VALUES ('82e376e4-6d42-46ec-a030-2a07ef9c9dee', '0313c321-740d-431f-aa79-fbe37c25536e', 'Glycolysis, Gluconeogenesis, Glycogenoses & Pyruvate Crossroads', 'PUBLISHED', 1)
