VALUES ('aac06054-ad7e-408f-afd7-c09c6c75ce69', 'c1400948-ee41-4907-af53-88f4fc9b28e3', 'Lipid Transport, Lipoproteins, Beta-Oxidation & Dyslipidemias', 'PUBLISHED', 1)
