INSERT INTO content_blocks (id, lesson_id, type, order_index, metadata)
VALUES ('130c4715-8c35-462c-a94e-2883c5cd3046', 'aac06054-ad7e-408f-afd7-c09c6c75ce69', 'CLINICAL_CASE', 2, '{"scenario":"An 8-year-old boy is evaluated for multiple painless nodular skin lesions over his Achilles tendons and extensor surfaces of his elbows. His father suffered a fatal myocardial infarction at age 34. Lipid panel demonstrates: Total Cholesterol 640 mg/dL (markedly elevated), LDL Cholesterol 560 mg/dL, HDL Cholesterol 42 mg/dL, and Triglycerides 140 mg/dL.","question":"Which of the following is the underlying molecular defect responsible for this patient","explanation":"Familial Hypercholesterolemia (Type IIa) is an autosomal dominant disorder caused by mutations in the LDL receptor gene (or ApoB-100). Impaired hepatic LDL clearance results in severe hypercholesterolemia (>500 mg/dL in homozygotes), pathognomonic Achilles tendon xanthomas, xanthelasmas, and accelerated premature coronary artery disease."}'::jsonb)
ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
