INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('2b16ddaf-2c89-480c-a46e-905fafbac26a', '242f70dd-f228-472e-a86d-1f1716899dca', 'DNA Replication & Repair: Telomerase (TERT), Xeroderma Pigmentosum (NER), Lynch Syndrome (MMR) & BRCA1/2 (HR)', 'PUBLISHED', 1)
