VALUES ('7ba52bb2-9722-4aeb-a4aa-aef1d1d481c1', 'ffd04d87-1f4f-4305-a7e4-7c5392b57a1d', 'Wiggers Diagram, Ventricular Pressure-Volume Loops, Preload/Afterload Shifts & Valvular Lesions', 'PUBLISHED', 1)
