INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('2783483b-3e66-47d3-a923-3d28f5841c69', '692297c8-b549-434a-a9d7-7ebd132ef188', 'Inpatient Fluid & Electrolyte Resuscitation: Holiday-Segar Rule, Hyponatremia Correction & Emergency Hyperkalemia Protocol', 'PUBLISHED', 1)
