VALUES ('f0e79602-b660-452b-ac91-3e58eeeaae64', '30223b90-78b8-40e3-a87d-13280595274e', 'Inpatient Ward Rounds & SOAP Documentation: Case Presentation Architecture, Daily Progress Notes & Medication Reconciliation', 'PUBLISHED', 1)
