VALUES ('56656f1b-affa-4d9a-a2c1-4ee6c335dd77', '2b2ba927-3677-4620-adba-28e3398a0d1f', 'Preoperative Risk Stratification: Revised Cardiac Risk Index (RCRI), ASA Physical Status, METs & Perioperative Medication Management', 'PUBLISHED', 1)
