VALUES ('a40dbb29-a720-47a7-a330-3a2a91d2a43e', '7fb7189e-ac19-4a84-a135-d3e5f7287861', 'Demography, Vital Health Indicators, DALYs, QALYs & Health Economics', 'PUBLISHED', 1)
