VALUES ('02090b22-6089-41ba-abf9-64625ce5d530', '2e0313d3-fde9-4e91-aff8-4b34860fd70d', '3D_MODEL', 3, '{"target":"BRAIN","viewer":"ThreeJS_LayeredDissection","title":"ICU Sedation (PADIS Guidelines), CAM-ICU Delirium Scoring & The ABCDEF Liberation Bundle — 3D Anatomical Spatial Model"}'::jsonb)
