INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('340d618b-2fb7-496a-af59-3df6b19b549a', 'a1c1b278-497f-466a-af48-f3957374ac2e', 'Dermatology: Psoriasis Vulgaris (Auspitz Sign, Koebner Phenomenon) & Lichen Planus', 'PUBLISHED', 1)
