INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('cc772f62-5657-4874-ac12-cecc9333bd49', 'f4029da7-5796-4619-acec-5f67d7ae400c', 'Inflammatory & Infectious Dermatoses: Psoriasis (IL-17A / IL-23 Biologics, Auspitz) & Necrotizing Fasciitis (LRINEC)', 'PUBLISHED', 1)
