VALUES ('b1101643-e188-47a5-a5b4-6e0e8978b14b', '3584e30d-1e8c-49db-ae11-4705a91cfe37', 'Interprofessional Communication & Team Dynamics: SBAR Handover, TeamSTEPPS, CUS Mnemonic & Two-Challenge Rule', 'PUBLISHED', 1)
