INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('b24eade7-feb0-4ed4-a3ba-dc7becbeb7e0', '3128f24f-0f8f-47ae-a48c-32d4b46ba644', 'Emergency: ATLS Primary Survey (ABCDE), Tension Pneumothorax & Massive Transfusion (MTP)', 'PUBLISHED', 1)
