VALUES ('b0a48ac9-7523-4808-a5a7-d40364b006c0', 'd05def68-ee5a-4973-a2a7-bd50a3f8115d', 'Advanced Cardiac Life Support (ACLS): Shockable vs Non-Shockable Arrest, H', 'PUBLISHED', 1)
