INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('afe02d40-8d7d-47d7-a4c1-e483f391798d', '43c79ff0-e1c4-4b68-a98e-d2de75bb73a7', 'Emergency Toxicology: Clinical Toxidromes (Cholinergic, Anticholinergic, Opioid, Sympathomimetic) & Antidotes', 'PUBLISHED', 1)
