VALUES ('685b12cd-4d37-442e-ad91-c0469722f87a', '79a03235-5a43-4238-a922-d5f8318d91d4', 'Shock Classification (Hypovolemic, Cardiogenic, Distributive, Obstructive) & Sepsis Resuscitation', 'PUBLISHED', 1)
