VALUES ('012af8cb-8f98-4a17-a935-e43302ea0d2a', '8fd77132-1074-4a69-a4fe-868ac44ba82a', 'ENT: Otitis Media, Unsafe Cholesteatoma, Meniere', 'PUBLISHED', 1)
