VALUES ('795a4bc0-b591-43ee-a6f6-8acb2f9418a5', '39ddb98d-a546-45ec-af02-f714f689d3a7', 'ENT: Deep Neck Space Infections (Quinsy, Ludwig', 'PUBLISHED', 1)
