INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('8ad90079-bdd5-42d0-af6b-df9403ec8092', 'ff966bef-b4a0-4f4f-a0c8-17e06627b77f', 'Vestibular Pathology & Neurotology: BPPV (Dix-Hallpike / Epley), Ménière Disease & Acoustic Neuroma', 'PUBLISHED', 1)
