VALUES ('ef5bd6fe-997d-4fde-a2bf-992d9c05d13f', 'dba5e956-9ff1-41fa-a059-3ed84b7a9852', 'Chronic Disease Protocols: ACC/AHA Hypertension Algorithms, ADA 2024 Diabetes Management & ASCVD Statin Stratification', 'PUBLISHED', 1)
