VALUES ('ef411da2-74f6-4d1e-ae5a-0f5175185fbc', 'c79b7e05-1ea2-470b-a88a-f5a3fbdb6796', 'Forensic Toxicology: Heavy Metals, Cyanide, Carbon Monoxide & Agricultural Poisons', 'PUBLISHED', 1)
