VALUES ('fa79945c-6183-4bc0-ae23-fa0a92ac4489', '05ff12f2-a976-4a54-a455-fc426a33706c', 'Medical Jurisprudence, Legal Inquests, Medical Negligence & Autopsy Protocols', 'PUBLISHED', 1)
