VALUES ('9e82f379-0799-461c-add7-41cccba91e36', 'b55f2ac8-5763-4710-a2e3-da73fd9dbe34', 'Thanatology: Post-Mortem Interval (PMI), Rigor, Livor, Algor Mortis & Decomposition', 'PUBLISHED', 1)
