VALUES ('a8548443-3560-4bd7-a1fb-19f12e3f89e2', '010c0e80-67bf-4bc5-af67-aae293f721b3', 'Traumatology: Mechanical Wounds, Firearm Ballistics & Asphyxial Deaths', 'PUBLISHED', 1)
