INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('8eb8e9a6-394a-4921-a10b-21b8f84417b0', 'd4a131a1-edec-42d9-a5a6-4819fade7a55', 'Mechanical Asphyxia: Hanging vs Ligature Strangulation vs Throttling & Drowning Pathophysiology', 'PUBLISHED', 1)
