INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('5ffcb639-0117-4f57-acb5-bd25b224a782', '9387a396-0681-406c-ace8-3cd3882573d1', 'Thanatology & Postmortem Interval (PMI): Algor, Rigor, Livor Mortis & Putrefactive Cascades', 'PUBLISHED', 1)
