INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('12c84aa9-8d30-460d-a5fb-f7762021206a', '44d1f9bc-c9e7-47d1-acdf-e1e1ad4a037b', 'Hospital Infection Control: WHO 5 Moments for Hand Hygiene, Standard & Transmission Precautions, PPE & NSI Prophylaxis', 'PUBLISHED', 1)
