VALUES ('4b59e276-75e3-45ce-a19e-ef66676fb054', '53d2aee3-56aa-44d9-ae13-13e856921300', 'Inflammatory Bowel Disease: Crohn Disease vs Ulcerative Colitis & Extraintestinal Manifestations', 'PUBLISHED', 1)
