INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('f8c7a44a-a579-4ed5-a605-1b9b5993e413', 'd67389a5-4ac5-467a-ad09-24a5cf707882', 'Anemia Diagnostic Algorithms: Microcytic Iron/Thalassemia, Normocytic Hemolysis & Macrocytic B12/Folate', 'PUBLISHED', 1)
