INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('23c1a0b0-7a5b-4698-a750-83667f74a0e3', '8c6726a3-0000-4e56-a8e0-7e545ee88a9e', 'Patient Safety (IPSG 1-6), Sentinel Events, WHO Surgical Safety Checklist & Root Cause Analysis (Fishbone/RCA)', 'PUBLISHED', 1)
