VALUES ('b48dd7e0-0212-48dc-ae21-dc97133fb729', 'ac44f579-9f15-4f71-a7e2-1ec4f67485e3', 'Immune Checkpoint Inhibitors (CTLA-4, PD-1, PD-L1) & Immune-Related Adverse Events (irAEs)', 'PUBLISHED', 1)
