VALUES ('84940c00-a137-44c6-a5ac-9efe8a48d17f', '9b0e4726-1f75-48d1-a67b-a9af5c7cf16c', 'Cellular Mechanisms of Hypersensitivity: Gell-Coombs Types I-IV, CDC, ADCC & T-Cell Cytotoxicity', 'PUBLISHED', 1)
