VALUES ('97bce00c-1763-4e57-adc8-8669a0fd2905', 'a4ca0e19-16fa-4558-ae46-454866b00f8b', 'Sepsis-3 Consensus, SOFA/qSOFA Scoring, Septic Shock & Surviving Sepsis Campaign Hour-1 Bundle', 'PUBLISHED', 1)
