VALUES ('2f4233cb-7f06-4fc8-af65-d08fe85b0150', 'ca0de1f5-07bc-4d43-adac-a0d76f91e1c1', 'Trauma Resuscitation: ATLS ABCDE Primary Survey, Massive Transfusion Protocol (1:1:1), TXA & FAST Ultrasound', 'PUBLISHED', 1)
