INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('ed4c99b0-b910-4371-afe9-67ca2ee31714', 'edbdef58-ad48-4783-ab8a-579457891a98', 'Pediatric Advanced Life Support (PALS 2025): Symptomatic Bradycardia (HR <60 CPR), Defibrillation & Shock Resuscitation', 'PUBLISHED', 1)
