VALUES ('5157bb6a-d049-4880-ab41-0cb76280f0d2', 'fedffdcb-fc74-43d7-a66e-e6fdb8c6de1f', 'Obstetric Emergencies: Postpartum Hemorrhage (4 Ts & Uterotonic Escalation) & Severe Preeclampsia / Eclampsia', 'PUBLISHED', 1)
