INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('b71c403e-f049-4ea7-a1f2-262c3428e7bc', '29d07317-d3d1-4023-aa58-892228a3fa95', 'Acute Coronary Syndromes: STEMI Reperfusion Timelines (<=90m Door-to-Balloon), NSTEMI Risk Stratification & Dual Antiplatelet Therapy', 'PUBLISHED', 1)
