VALUES ('c198c74b-6492-4f93-aadf-6765468b1dcc', '01572689-3725-4712-ac9d-50eccf152fe2', 'Necrotizing Soft Tissue Infections: LRINEC Score (>=6), Emergent Surgical Debridement & Clindamycin Toxin Shutdown', 'PUBLISHED', 1)
