INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('3a4af911-a454-48ee-aa64-8b96120348f9', '83126f95-320c-4c3a-a084-3c41d2c99d6f', 'Emergency Psychiatry: Neuroleptic Malignant Syndrome (NMS vs Serotonin Syndrome), Acute Agitation & Rapid Tranquilization', 'PUBLISHED', 1)
