INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('d0b451fe-e1ec-45aa-ab3d-07aa099f7e2d', 'eb79e128-af9c-4e85-ab5f-25bfbf7e0fbd', 'Entrustable Professional Activities: The 13 Core EPAs, Chen', 'PUBLISHED', 1)
