INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('dace089a-4e18-43bc-a342-e890f33090ab', '5448094e-3031-41aa-a2fc-6363debd0159', 'Quality Improvement & Patient Safety: Root Cause Analysis (Ishikawa 6Ms & 5 Whys), PDSA Cycles & SBAR Handover', 'PUBLISHED', 1)
