VALUES ('4089f099-0b86-4071-a984-d1f1cb1c8cf6', 'b8e32c4e-fded-4d10-a0d0-38b8116071b8', 'Advanced Acid-Base & ABG Interpretation: Winter', 'PUBLISHED', 1)
