VALUES ('03b84826-edec-48f3-ac14-5a6bbd868e18', '209c707a-f584-402e-aae4-636cbbec2882', 'Gram-Positive & Gram-Negative Bacteria: Morphological Flowcharts & Clinical Syndromes', 'PUBLISHED', 1)
