VALUES ('a38b33d5-1036-4fa3-a5b1-2570dad8a7d8', '348ccd4e-6033-48d7-ac9d-d4b658bc5a80', 'Aphasia Syndromes (Broca vs Wernicke vs Conduction), Gerstmann Syndrome & Visual Field Deficits', 'PUBLISHED', 1)
