VALUES ('72775c14-781d-4aac-a726-d1a397755d1e', '73b7c6f9-4c8b-4e8f-a00b-2e75fd536715', 'Multiple Sclerosis, Guillain-Barré, Myasthenia Gravis, Parkinson & Huntington', 'PUBLISHED', 1)
