VALUES ('21832219-9fd0-433e-af63-a6682eeb7a3e', '180269f6-3747-43fc-ad98-dd0cd514f58d', 'Acute Ischemic Stroke Syndromes, Aphasias & Brainstem Vascular Neuro-Localization', 'PUBLISHED', 1)
