VALUES ('df7d30e6-a881-4be0-aed3-0bcd8e475c7a', '9a8b6c54-2097-4f59-a825-7a6c48675fe3', 'Spinal Cord Syndromes (Brown-Séquard, Anterior, Central Syringomyelia) & ALS', 'PUBLISHED', 1)
