VALUES ('d916e6d5-62b1-47c5-ad5f-f3593969a2fd', '36c54565-5e4b-4c11-a607-268a3597f3cb', 'Planar Scintigraphy & SPECT-CT: Bone Scan, V/Q Lung Scan, HIDA Cholecystitis & Renal Scintigraphy', 'PUBLISHED', 1)
