VALUES ('6382b76f-dcef-4ec6-af46-db8d54522761', 'a2c9d0cc-da0b-4dc7-a0c1-363967428869', 'Electronic Fetal Monitoring (EFM): NICHD Categories I-III, Decelerations (VEAL CHOP) & Resuscitation', 'PUBLISHED', 1)
