INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('a8d30d21-95ae-4136-ae8f-ac77f47e6494', 'a7f9168f-7f57-4808-a00b-e54393a42290', 'Postpartum Hemorrhage (PPH): The 4 ', 'PUBLISHED', 1)
