VALUES ('e4e23f6e-9a34-442d-acd3-39a77f3d7988', 'd777ccec-d5c7-4eb5-ab93-32c465f653b8', 'Cancer Biology, Hallmarks of Malignancy, Genomic Drivers & AJCC TNM 8th Edition Staging', 'PUBLISHED', 1)
