INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('426736ab-dd4b-4da7-af7d-d5f363b4c03d', '4cf38df0-85ed-4463-a709-268dcc01bd2e', 'Oncologic Emergencies (SVC Syndrome, Spinal Cord Compression, Tumor Lysis) & Palliative Analgesia (WHO Pain Ladder)', 'PUBLISHED', 1)
