INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('4b458182-890e-4a4f-abc2-5fd823675d18', 'dcaef5cc-cdb4-4fa0-aced-69074693182f', 'Uveitis & Ocular Immunology: HLA-B27 Anterior Hypopyon, Toxoplasmosis & CMV Retinitis', 'PUBLISHED', 1)
