INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('d01ea3ce-a20e-42da-a3a3-41994e78d6fc', 'f1ec99f1-3788-4864-a48e-e63d2752a292', 'Acute Compartment Syndrome (ACS): The 6 ', 'PUBLISHED', 1)
