VALUES ('1f56ac37-0f24-44e3-ad96-102f6d4b5799', '03dbf07e-25df-4865-afe5-2da11bb114a0', 'Musculoskeletal Oncology: Osteosarcoma, Ewing Sarcoma, Giant Cell Tumor & Chondrosarcoma', 'PUBLISHED', 1)
