INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('87ad80ac-7587-4f65-a1a8-c306731bb0c7', 'abdede3a-70b3-4673-af65-e7b0cc94ab5f', 'Pediatric Orthopedics: Developmental Dysplasia (DDH), SCFE & Legg-Calvé-Perthes Disease', 'PUBLISHED', 1)
