VALUES ('d08e65a3-6074-43ba-a45f-05f5bbaa0c83', 'a086eeb5-2320-4909-af7d-5406bfa1af66', 'OSCE Station: SPIKES Breaking Bad News & Obstetric Leopold Maneuvers with Partograph', 'PUBLISHED', 1)
