INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('3e3dd0b0-1cb7-47f2-a33b-eae4acd9dccd', 'e3babc6a-9a64-497a-ae94-0335f712cf92', 'OSCE Station: ATLS Trauma Primary Survey & AHA ACLS Cardiac Arrest MegaCode Simulation', 'PUBLISHED', 1)
