VALUES ('61fcf5fd-3918-467f-a913-a441c1983776', 'baf945a3-c2c9-4d9c-ae55-56204309dddb', 'OSCE Station: Suture Selection, Surgical Knot Tying & ABG Acid-Base Interpretation', 'PUBLISHED', 1)
