VALUES ('988d8f72-b2e1-4d13-a82d-5dff342eca91', '3289b2fa-9bd7-433a-a362-f73b6d7c57ad', 'Myocardial Infarction Timeline, Glomerulonephritis & Diagnostic Stains', 'PUBLISHED', 1)
