VALUES ('086c429f-2513-436f-a0e8-d560018775eb', 'f6996fa7-a68e-4161-ab49-a4e11597af97', 'Neonatology: NRP 8th Ed Algorithm, APGAR Score & Respiratory Distress Syndrome (Surfactant)', 'PUBLISHED', 1)
