VALUES ('c643d828-456a-490d-a5c2-76c2fb4520fa', '3d7d39d0-10ad-4323-aa80-ca49c4bdf382', 'Neonatal Respiratory Distress: Surfactant RDS, TTN, Meconium Aspiration & BPD', 'PUBLISHED', 1)
