VALUES ('4b0e8822-4307-48d8-a1f5-1fc2d2bff7ea', '9b13caf3-70bb-4628-a629-37b515d4950d', 'Pediatric Immunodeficiencies (SCID, Bruton, WAS) & Inborn Errors (PKU, Galactosemia)', 'PUBLISHED', 1)
