INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('d79487d1-f218-4891-aabe-b18586726829', '2777cc3a-f88a-40ed-ab9d-22ec1c3d9f14', 'Advanced Mechanical Ventilation: ARDSNet Lung-Protective Strategy, Driving Pressure, Prone Positioning & Asynchronies', 'PUBLISHED', 1)
