VALUES ('828201ae-802a-42a3-a03b-7303c57ae82e', '61f42c35-2ec1-4af9-a7a7-0076a56cc3d9', 'Residency Core Competencies: ACGME Milestones, Systems-Based M&M Audits, Cognitive Heuristics & Crisis Resource Management', 'PUBLISHED', 1)
