INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('a7b177f5-2c20-4805-a4ca-a89e2427e8ca', '4addb9bd-12a4-4c57-a34d-db081e3bcc78', 'Sepsis-3 Precision Resuscitation: Clinical Phenotyping (Alpha-Delta), Dynamic Fluid Responsiveness & De-escalation', 'PUBLISHED', 1)
