INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('69f1a17e-98df-4af1-af2c-0daca75eeec2', '21591ca8-0dc6-4cdc-ab08-8414f6ef403f', 'Catatonia, Neuroleptic Malignant Syndrome (NMS) & Serotonin Syndrome: Diagnostic Differentiation & Protocols', 'PUBLISHED', 1)
