INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('86cfa2cf-a51f-4de1-acfa-cab72a924eea', '3dfcd87c-8713-4657-af39-d07b53ad9d37', 'Treatment-Refractory Schizophrenia (TRS): Clozapine Titration, ANC Monitoring & REMS Guidelines', 'PUBLISHED', 1)
ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, title = EXCLUDED.title, status = 'PUBLISHED';
INSERT INTO content_blocks (id, lesson_id, type, order_index, metadata)
VALUES ('5b2bacc4-83a9-4d85-a5a2-ed4a8b578387', '86cfa2cf-a51f-4de1-acfa-cab72a924eea', 'EXPLANATION', 1, '{"text":"# Treatment-Refractory Schizophrenia (TRS) & Clozapine REMS Protocols\n\nClozapine is the only evidence-based antipsychotic proven to reduce positive psychotic symptoms, suicidal behavior, and aggressive violence in treatment-refractory schizophrenia, but requires strict Absolute Neutrophil Count (ANC) pharmacovigilance.\n\n---\n\n## 1. Absolute Neutrophil Count (ANC) Monitoring Protocols (FDA REMS)\n\n$$\\\\begin{array}{lcccc}\n\\\\hline\n\\\\textbf{Patient Population} & \\\\textbf{Baseline ANC Requirement} & \\\\textbf{Monitoring Schedule} & \\\\textbf{ANC Action Thresholds} \\\\\\\\\n\\\\hline\n\\\\textbf{General Population} & \\\\mathbf{\\\\text{ANC } \\\\ge 1,500/\\\\mu\\\\text{L}} & \\\\text{Weekly (Months 1-6)} & \\\\mathbf{\\\\text{ANC } 1,000-1,499: \\\\text{ Continue, test 3x/week}} \\\\\\\\\n& & \\\\text{Biweekly (Months 7-12)} & \\\\mathbf{\\\\text{ANC } < 1,000: \\\\text{ SUSPEND IMMEDIATELY}} \\\\\\\\\n& & \\\\text{Monthly (Thereafter)} & \\\\mathbf{\\\\text{ANC } < 500: \\\\text{ STOP PERMANENTLY (Agranulocytosis)}} \\\\\\\\\n\\\\textbf{Benign Ethnic Neutropenia (BEN)} & \\\\mathbf{\\\\text{ANC } \\\\ge 1,000/\\\\mu\\\\text{L}} & \\\\text{Same interval schedule} & \\\\mathbf{\\\\text{ANC } < 500: \\\\text{ SUSPEND / Hematology consult}} \\\\\\\\\n\\\\hline\n\\\\end{array}$$\n\n---\n\n## 2. Clozapine Pharmacotherapy & High-Yield Adverse Effects\n\n$$\\\\begin{array}{lcccc}\n\\\\hline\n\\\\textbf{Adverse Effect / Target} & \\\\textbf{Incidence \\\\& Timing} & \\\\textbf{Clinical Hallmarks} & \\\\textbf{Management \\\\& Safety Rules} \\\\\\\\\n\\\\hline\n\\\\textbf{Therapeutic Serum Level} & \\\\text{Trough target} & \\\\mathbf{350-600\\\\text{ ng/mL}} & \\\\text{Dose titrations; smoking induces CYP1A2} \\\\\\\\\n\\\\textbf{Myocarditis} & \\\\text{First 4-6 weeks (0.1-1\\\\%)} & \\\\text{Chest pain, fever, tachycardia, dyspnea} & \\\\mathbf{\\\\text{Check Troponin + CRP; STOP IF ELEVATED}} \\\\\\\\\n\\\\textbf{Severe Constipation / Ileus} & \\\\text{Anytime (up to 30\\\\%)} & \\\\text{Abdominal distension, obstipation, vomiting} & \\\\mathbf{\\\\text{Mandatory bowel regimen (PEG); high mortality!}} \\\\\\\\\n\\\\textbf{Dose-Dependent Seizures} & > 600\\\\text{ mg/day (3-5\\\\%)} & \\\\text{Myoclonic jerks, generalized tonic-clonic} & \\\\text{Add Valproate (avoids CYP induction)} \\\\\\\\\n\\\\hline\n\\\\end{array}$$","unitCode":"PG10.3","estimatedMinutes":180,"organ3dTarget":null}'::jsonb)
ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO content_blocks (id, lesson_id, type, order_index, metadata)
VALUES ('ce06771d-e1b5-43f3-a125-4d3bf0633ba6', '86cfa2cf-a51f-4de1-acfa-cab72a924eea', 'CLINICAL_CASE', 2, '{"scenario":"A 28-year-old male with an 8-year history of chronic paranoid schizophrenia continues to experience persecutory auditory hallucinations, command delusions, and severe agitation despite consecutive full 8-week therapeutic trials of Risperidone (6 mg/day) and Olanzapine (20 mg/day) with verified treatment adherence. Medical workup and baseline labs show WBC 6,800/uL and Absolute Neutrophil Count (ANC) 3,900/uL. He has no history of blood dyscrasias.","question":"What is the diagnosis, what is the indicated next-line antipsychotic, and what is the mandatory ANC monitoring schedule during the first year of therapy?","explanation":"This case demonstrates classic Treatment-Refractory Schizophrenia (TRS): (1) Definition: Failure of >=2 adequate trials of first-line antipsychotics (including second-generation) confirms TRS; (2) Clozapine Efficacy: Clozapine is uniquely effective for refractory positive symptoms and reducing suicide risk; (3) REMS Monitoring: Due to the risk of severe neutropenia/agranulocytosis, weekly ANC monitoring for 6 months, then biweekly for 6 months, then monthly is legally mandated."}'::jsonb)
ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
