VALUES ('0d0de846-4d26-408b-a8b1-c5121f82397c', '79b42f24-4254-40c7-affe-b17c9dbeb736', 'Treatment-Resistant Depression (TRD): Augmentation, ECT Seizure Titration, rTMS & Esketamine Protocols', 'PUBLISHED', 1)
