INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('39d6459f-1b48-4090-ad25-ad13ecd9fd86', '6a9c0e15-24ac-4820-a72e-4df6bbc1b025', 'Traumatic Brain Injury (TBI): Rancho Los Amigos Cognitive Staging (I-X), Disorders of Consciousness & SCAT-6', 'PUBLISHED', 1)
