VALUES ('e8d2682e-4249-4325-aec5-1c4535f1f24e', 'd9e4d644-9fd4-4c8b-a850-1f6bd87ca3dc', 'Rapidly Progressive Glomerulonephritis (RPGN): Renal Biopsy Pathology, Immunofluorescence & ANCA Vasculitis', 'PUBLISHED', 1)
