INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('e58e5fa3-70ea-4d2b-a167-dd0eb990f8da', 'bce30dd2-7364-4e61-ad0f-2affe8c9f959', 'Damage Control Laparotomy: The Trauma Lethal Triad, 3-Stage Paradigm & Abdominal Compartment Syndrome', 'PUBLISHED', 1)
