VALUES ('b7051385-318e-4cd2-a744-3de62f902283', '14cae5c0-62e5-4d6a-a5ac-afc02302fe62', 'Viscoelastometry in Trauma: TEG / ROTEM Parameters, Goal-Directed Transfusion & CRASH-2 TXA Protocols', 'PUBLISHED', 1)
