INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('4a2c4dad-e998-41c2-a3a9-65cb4f0accc6', '6c3382e1-d821-4dee-a173-ee6c26ec9e63', 'Extreme Prematurity: Less Invasive Surfactant Administration (LISA / MIST), CPAP & BPD Prevention', 'PUBLISHED', 1)
