INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('11b63e4c-5e60-4311-ab12-017ec1dc6899', '12eff56f-6ac6-4a5d-ab5a-f50237fdb441', 'Neonatal Hypoxic-Ischemic Encephalopathy (HIE): Sarnat Staging, 72h Therapeutic Hypothermia & aEEG', 'PUBLISHED', 1)
