INSERT INTO concepts (id, topic_id, title, sort_order)
VALUES ('1229640c-8636-4a08-a31b-e688ba05502e', '80e76400-8eba-407e-aaf9-6498499436b0', 'Early-Onset Fetal Growth Restriction (FGR): Umbilical Artery AREDF, MCA Brain Sparing & Ductus Venosus', 1)
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('12c49a2d-ea5c-480f-ab25-a2f96a659eb7', '1229640c-8636-4a08-a31b-e688ba05502e', 'Early-Onset Fetal Growth Restriction (FGR): Umbilical Artery AREDF, MCA Brain Sparing & Ductus Venosus', 'PUBLISHED', 1)
ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, title = EXCLUDED.title, status = 'PUBLISHED';
INSERT INTO content_blocks (id, lesson_id, type, order_index, metadata)
VALUES ('13a5478b-2a8b-4978-aced-0613fa31dd71', '12c49a2d-ea5c-480f-ab25-a2f96a659eb7', 'EXPLANATION', 1, '{"text":"# Early-Onset FGR & Longitudinal Doppler Velocimetry\n\nPlacental villous vascular obliteration progresses predictably from the umbilical artery to cerebral vasodilation and precordial venous failure.\n\n---\n\n## 1. Longitudinal Doppler Progression & Delivery Benchmarks\n\n$$\\\\begin{array}{lcccc}\n\\\\hline\n\\\\textbf{Vascular Bed} & \\\\textbf{Doppler Waveform Pattern} & \\\\textbf{Physiological Mechanism} & \\\\textbf{Delivery Trigger / Action} \\\\\\\\\n\\\\hline\n\\\\textbf{Umbilical Artery (UA)} & \\\\text{Elevated Pulsatility Index (PI } > 95\\\\text{th\\\\%)} & \\\\text{Placental vascular resistance rise} & \\\\text{Twice weekly Doppler monitoring} \\\\\\\\\n\\\\textbf{UA AEDF} & \\\\mathbf{\\\\text{Absent End-Diastolic Flow}} & \\\\mathbf{> 50-60\\\\% \\\\text{ placental vascular bed obliterated}} & \\\\mathbf{\\\\text{Deliver at } 33-34\\\\text{ wks (after steroids)}} \\\\\\\\\n\\\\textbf{UA REDF} & \\\\mathbf{\\\\text{Reversed End-Diastolic Flow}} & \\\\mathbf{> 70\\\\% \\\\text{ placental obliteration; extreme afterload}} & \\\\mathbf{\\\\text{Deliver at } 30-32\\\\text{ wks (after steroids)}} \\\\\\\\\n\\\\textbf{Middle Cerebral (MCA)} & \\\\mathbf{\\\\text{Low PI (} < 5\\\\text{th\\\\%}) \\\\text{; CPR } < 1.08} & \\\\mathbf{\\\\text{Brain-Sparing Autoregulation (Hypoxia)}} & \\\\text{Close surveillance for venous decompensation} \\\\\\\\\n\\\\textbf{Ductus Venosus (DV)} & \\\\mathbf{\\\\text{Absent or Reversed a-Wave}} & \\\\mathbf{\\\\text{Severe Right Ventricular Diastolic Failure}} & \\\\mathbf{\\\\text{EMERGENCY DELIVERY at } \\\\ge 26-28\\\\text{ wks}} \\\\\\\\\n& \\\\mathbf{(\\\\text{during atrial contraction)}} & \\\\mathbf{\\\\& \\\\text{ Metabolic Acidemia (TRUFFLE Trial)}} & \\\\mathbf{(\\\\text{after Betamethasone rescue})} \\\\\\\\\n\\\\hline\n\\\\end{array}$$\n\n---\n\n## 2. The TRUFFLE Trial Paradigm\n\n- **Key Evidence**:\n  - Waiting for **Ductus Venosus (DV) late changes (absent/reversed a-wave)** or computerized CTG short-term variation (STV $<3.5\\\\text{ ms}$) prior to delivery between $26$ and $32\\\\text{ weeks}$ maximizes neurological intact survival without increasing stillbirth rates compared to early delivery based solely on arterial umbilical waveforms.\n- **Antenatal Corticosteroids & Magnesium Sulfate**:\n  - Administer **Betamethasone ($12\\\\text{ mg}$ IM Q24H $\\\\times 2$ doses)** for lung maturation and **Magnesium Sulfate ($4\\\\text{ g}$ IV load $+ 1\\\\text{ g/h}$ infusion)** for neuroprotection against cerebral palsy if delivery occurs at $<32\\\\text{ weeks}$.","unitCode":"PG5.2","estimatedMinutes":180,"organ3dTarget":null}'::jsonb)
ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO content_blocks (id, lesson_id, type, order_index, metadata)
VALUES ('71c20bef-13e3-4bdd-abf2-84d8a14b6ec4', '12c49a2d-ea5c-480f-ab25-a2f96a659eb7', 'CLINICAL_CASE', 2, '{"scenario":"A 32-year-old multigravida at 29 weeks gestation is admitted with severe early-onset fetal growth restriction (estimated fetal weight 720g, <3rd percentile). Fetal Doppler velocimetry reveals: Umbilical Artery shows Reversed End-Diastolic Flow (REDF), Middle Cerebral Artery shows marked vasodilation with PI of 0.88 (<5th percentile, confirming brain sparing), and Ductus Venosus Doppler demonstrates persistent Reversed a-Wave during atrial systole. Computerized cardiotocography reveals a baseline fetal heart rate of 135 bpm with reduced short-term variation (STV = 2.8 ms).","question":"What is the clinical interpretation of the Ductus Venosus reversed a-wave, and what is the definitive obstetric management?","explanation":"This case illustrates critical early-onset FGR Doppler progression: (1) Pathophysiology: Umbilical artery REDF indicates >70% placental bed obliteration, and MCA vasodilation reflects brain-sparing autoregulation. However, Ductus Venosus a-wave reversal reflects backward transmission of elevated right atrial pressure during myocardial failure and severe acidosis; (2) Delivery Trigger: In the TRUFFLE trial, DV a-wave reversal at >=26-28 weeks represents the ultimate safety boundary mandating emergency delivery to prevent intrauterine fetal demise."}'::jsonb)
ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
