INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('bbf87ada-448a-4d0f-a582-6bd4986b0e52', 'cf45cd5a-02eb-4b6f-a3ec-47d9faa224e7', 'Monochorionic Twin Gestations: Twin-to-Twin Transfusion Syndrome (TTTS), Quintero Staging & Solomon Laser', 'PUBLISHED', 1)
