INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('03db877e-ed2f-4c0a-ad03-d13da6f70d1a', '130dd5bb-ef1b-4095-ac20-9739f08a33f6', 'Resuscitative Hysterotomy (PMCD): The 4-Minute Rule, Aortocaval Decompression & Maternal CPR', 'PUBLISHED', 1)
ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, title = EXCLUDED.title, status = 'PUBLISHED';
INSERT INTO content_blocks (id, lesson_id, type, order_index, metadata)
VALUES ('40133d78-123c-4b01-a9b3-fbc315f103ab', '03db877e-ed2f-4c0a-ad03-d13da6f70d1a', 'EXPLANATION', 1, '{"text":"# Resuscitative Hysterotomy (Peri-Mortem Cesarean Delivery - PMCD)\n\nResuscitative hysterotomy is primarily a maternal resuscitation procedure executed to relieve fatal aortocaval compression and restore maternal venous return.\n\n---\n\n## 1. Physiological Basis & The 4-Minute Rule\n\n$$\\\\begin{array}{lcccc}\n\\\\hline\n\\\\textbf{Parameter} & \\\\textbf{Clinical Standard / Protocol Target} & \\\\textbf{Physiological Rationale} \\\\\\\\\n\\\\hline\n\\\\textbf{Gestational Age Threshold} & \\\\mathbf{\\\\ge 20\\\\text{ weeks (Fundus at/above Umbilicus)}} & \\\\mathbf{\\\\text{Uterus compresses IVC/Aorta, reducing venous}} \\\\\\\\\n& & \\\\mathbf{\\\\text{return by up to } 60\\\\% \\\\text{ and nullifying CPR}} \\\\\\\\\n\\\\textbf{Continuous Left Uterine} & \\\\mathbf{\\\\text{Manual Left Lateral Uterine Displacement (LUD)}} & \\\\text{Displaces gravid uterus off retroperitoneal vessels} \\\\\\\\\n\\\\textbf{Displacement (LUD)} & & \\\\text{without tilting chest compression axis} \\\\\\\\\n\\\\textbf{Decision-to-Incision} & \\\\mathbf{4\\\\text{ minutes of refractory maternal cardiac arrest}} & \\\\text{If no ROSC at 4 min, begin immediate laparotomy} \\\\\\\\\n\\\\textbf{Delivery Benchmark} & \\\\mathbf{\\\\text{Complete fetal extraction by } 5\\\\text{ minutes}} & \\\\mathbf{\\\\text{Immediate relief of IVC obstruction increases}} \\\\\\\\\n& & \\\\mathbf{\\\\text{maternal cardiac output by } 30-40\\\\% \\\\rightarrow \\\\text{ROSC}} \\\\\\\\\n\\\\hline\n\\\\end{array}$$\n\n---\n\n## 2. Procedural Execution: Bedside Surgical Standards\n\n- **Location**:\n  - Perform **where the arrest occurs** (Labor & Delivery room, Emergency Department, or ICU); **NEVER delay resuscitation by transporting the patient to the Operating Room**.\n- **Preparation**:\n  - **No antiseptic skin prep, no sterile drapes, and no waiting for surgical instrumentation or anesthesia**.\n- **Incision**:\n  - Rapid midline vertical skin incision from symphysis pubis toward umbilicus with a scalpel; open peritoneal cavity; vertical hysterotomy incision into lower uterine segment; deliver infant and placenta; pack uterus.\n- **CPR Continuity**:\n  - Uninterrupted high-quality chest compressions ($100-120\\\\text{/min}$, depth $\\\\ge 5\\\\text{ cm}$, hands placed slightly higher on sternum due to upward diaphragmatic elevation).","unitCode":"PG5.4","estimatedMinutes":180,"organ3dTarget":null}'::jsonb)
ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO content_blocks (id, lesson_id, type, order_index, metadata)
VALUES ('e4001669-72d0-406a-ad74-5e932f999b6c', '03db877e-ed2f-4c0a-ad03-d13da6f70d1a', 'CLINICAL_CASE', 2, '{"scenario":"A 26-year-old primigravida at 32 weeks gestation collapses in the emergency department waiting room with sudden witnessed asystolic cardiac arrest. High-quality CPR is initiated with continuous manual left uterine displacement (LUD), bag-valve-mask ventilation with 100% O2, and IV epinephrine 1 mg is administered. At 4 minutes of resuscitation, there is no return of spontaneous circulation (ROSC) and CPR remains in progress.","question":"What is the mandatory next step in management according to maternal resuscitation guidelines, and what is the target delivery time?","explanation":"This case demonstrates the critical time-sensitive mandate of Resuscitative Hysterotomy: (1) The 4-Minute Rule: If maternal cardiac arrest at >=20 weeks gestation does not achieve ROSC within 4 minutes of CPR, resuscitative hysterotomy must begin immediately at the bedside; (2) The 5-Minute Delivery Goal: Extracting the fetus by 5 minutes eliminates aortocaval compression, instantly restoring up to 40% of maternal venous return and offering the highest chance of maternal neurological survival and ROSC."}'::jsonb)
ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;

