VALUES ('dcf999bd-305e-4962-a6fe-0cd2679bda8f', 'ca82c3d8-0bf7-4613-a192-5e65d0ddd9af', 'Local Anesthetic Systemic Toxicity (LAST): Bupivacaine Cardiotoxicity & 20% Lipid Emulsion Protocols', 'PUBLISHED', 1)
