INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('a06610f6-51c3-44d4-a68e-55d65a4be3ed', '77d1f3ae-5e6d-4975-aaee-af89e4854301', 'Malignant Hyperthermia (MH): RYR1 Pathophysiology, Hypermetabolic Crisis & Dantrolene Protocols', 'PUBLISHED', 1)
