INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('b918d7cd-8730-4df8-ab7e-82f99f3b831a', '95c24b59-84c6-431a-a06e-af63959558c7', 'Acute Compartment Syndrome (ACS): Delta Pressure Criteria & Emergent Dual-Incision Fasciotomies', 'PUBLISHED', 1)
ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, title = EXCLUDED.title, status = 'PUBLISHED';
INSERT INTO content_blocks (id, lesson_id, type, order_index, metadata)
VALUES ('30e420bb-d174-49cf-a2be-6468b901bdbb', 'b918d7cd-8730-4df8-ab7e-82f99f3b831a', 'EXPLANATION', 1, '{"text":"# Acute Compartment Syndrome (ACS) & Emergent Decompression Protocols\n\nAcute Compartment Syndrome occurs when tissue pressure within an enclosed fascial space exceeds capillary perfusion pressure, leading to muscle ischemia and irreversible necrosis after 6-8 hours.\n\n---\n\n## 1. Clinical Diagnostic Progression & Compartment Pressure Manometry\n\n$$\\\\begin{array}{lcccc}\n\\\\hline\n\\\\textbf{Diagnostic Sign / Parameter} & \\\\textbf{Clinical Feature / Criterion} & \\\\textbf{Diagnostic Sensitivity} & \\\\textbf{Physiological Basis} \\\\\\\\\n\\\\hline\n\\\\textbf{Earliest Sign} & \\\\mathbf{\\\\text{Pain out of proportion to injury}} & \\\\mathbf{\\\\text{Most sensitive early indicator}} & \\\\text{Ischemic stimulation of muscle spindle nociceptors} \\\\\\\\\n\\\\textbf{Pathognomonic Sign} & \\\\mathbf{\\\\text{Severe pain on passive stretch}} & \\\\mathbf{\\\\text{Hallmark of active muscle ischemia}} & \\\\text{Tension on ischemic, edematous muscle fibers} \\\\\\\\\n\\\\textbf{Neurological} & \\\\text{Paresthesia / Hypoesthesia in nerve distribution} & \\\\text{Early ischemic nerve dysfunction} & \\\\text{Deep peroneal (1st web space) / Tibial (plantar)} \\\\\\\\\n\\\\textbf{Late Signs (Do NOT wait!)} & \\\\text{Paralysis, Pallor, Pulselessness} & \\\\text{Late / Irreversible necrosis} & \\\\text{Complete microvascular and axonal infarction} \\\\\\\\\n\\\\textbf{Delta Pressure (}\\\\Delta P\\\\textbf{)} & \\\\mathbf{\\\\Delta P = \\\\text{Diastolic BP} - \\\\text{Compartment Pressure} \\\\le 30} & \\\\mathbf{\\\\text{Definitive surgical indication}} & \\\\text{Capillary collapse pressure threshold} \\\\\\\\\n\\\\hline\n\\\\end{array}$$\n\n---\n\n## 2. Anatomical Dual-Incision 4-Compartment Leg Fasciotomy\n\n- **Anterolateral Incision**:\n  - Placed midway between fibular shaft and anterior tibial crest.\n  - Decompresses:\n    - **Anterior Compartment**: Deep peroneal nerve, anterior tibial artery, tibialis anterior, EHL, EDL.\n    - **Lateral Compartment**: Superficial peroneal nerve, peroneus longus, peroneus brevis.\n- **Posteromedial Incision**:\n  - Placed $2\\\\text{ cm}$ posterior to the posterior border of the tibia.\n  - Decompresses:\n    - **Superficial Posterior Compartment**: Gastrocnemius, soleus, plantaris.\n    - **Deep Posterior Compartment**: Tibial nerve, posterior tibial vessels, flexor hallucis longus, flexor digitorum longus, tibialis posterior (releases soleus bridge from tibia).","unitCode":"PG7.3","estimatedMinutes":180,"organ3dTarget":null}'::jsonb)
ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO content_blocks (id, lesson_id, type, order_index, metadata)
VALUES ('c48b4f7d-238f-4e5b-acfb-10e89d3a76ea', 'b918d7cd-8730-4df8-ab7e-82f99f3b831a', 'CLINICAL_CASE', 2, '{"scenario":"A 22-year-old male is admitted following a closed, displaced midshaft tibia fracture treated with a posterior splint. Six hours post-injury, he develops escalating, excruciating leg pain unresponsive to multiple doses of IV morphine. On examination, the anterior and deep posterior leg compartments are tense, firm (","question":"What is the calculated Delta pressure (Delta P), what is the clinical diagnosis, and what is the definitive emergent surgical management?","explanation":"This case demonstrates acute compartment syndrome: (1) Delta Pressure: Delta P = Diastolic BP (60) - Compartment Pressure (38) = 22 mmHg. A Delta P <=30 mmHg confirms tissue hypoperfusion requiring emergency decompression; (2) Clinical Hallmarks: Pain out of proportion and pain with passive muscle stretch are the earliest sensitive signs; (3) Definitive Fasciotomy: Emergent dual-incision 4-compartment fasciotomy is mandatory to prevent muscle infarction, Volkmann contracture, and rhabdomyolysis."}'::jsonb)
ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO units (id, subject_id, title, sort_order)
