INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('1c0bd689-115e-4416-a33c-b9d6436baaff', '90b728b0-4f8a-4a72-a670-918aa70d905d', 'Musculoskeletal Oncology: Enneking Staging, Bone Sarcomas (Osteosarcoma/Ewing) & Limb Salvage', 'PUBLISHED', 1)
