INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('1abd02fa-b437-4c6e-a5f9-37d3ede48f7d', '604e1029-fd19-4744-a667-d3747069814e', 'High-Energy Open Fractures: Gustilo-Anderson Classification, MESS Limb Salvage & Antibiotic Protocols', 'PUBLISHED', 1)
ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, title = EXCLUDED.title, status = 'PUBLISHED';
INSERT INTO content_blocks (id, lesson_id, type, order_index, metadata)
VALUES ('44af171a-54a1-4912-a6e3-28910c64403e', '1abd02fa-b437-4c6e-a5f9-37d3ede48f7d', 'EXPLANATION', 1, '{"text":"# High-Energy Open Fractures, Gustilo-Anderson & MESS Limb Salvage\n\nOpen fractures are surgical emergencies requiring rapid antibiotic prophylaxis, staged operative debridement, and objective limb salvage scoring.\n\n---\n\n## 1. Gustilo-Anderson Classification & Antibiotic Protocols\n\n$$\\\\begin{array}{lcccc}\n\\\\hline\n\\\\textbf{Gustilo Grade} & \\\\textbf{Wound Size \\\\& Soft Tissue Pathology} & \\\\textbf{Infection Rate} & \\\\textbf{Antibiotic Prophylaxis Protocol} \\\\\\\\\n\\\\hline\n\\\\textbf{Type I} & \\\\text{Puncture } < 1\\\\text{ cm, clean, minimal crush} & 0-2\\\\% & \\\\mathbf{\\\\text{1st-Gen Cephalosporin (Cefazolin 2 g IV Q8H)}} \\\\\\\\\n\\\\textbf{Type II} & \\\\text{Laceration } 1-10\\\\text{ cm, moderate crush/stripping} & 2-7\\\\% & \\\\mathbf{\\\\text{Cefazolin 2 g IV Q8H}} \\\\\\\\\n\\\\textbf{Type IIIA} & \\\\mathbf{\\\\text{Crush } > 10\\\\text{ cm; adequate periosteal coverage}} & 10-15\\\\% & \\\\mathbf{\\\\text{Cefazolin + Aminoglycoside (Gentamicin 5 mg/kg)}} \\\\\\\\\n\\\\textbf{Type IIIB} & \\\\mathbf{\\\\text{Extensive periosteal loss, bone exposed (needs flap)}} & 20-30\\\\% & \\\\mathbf{\\\\text{Cefazolin + Gentamicin (add Penicillin G for soil)}} \\\\\\\\\n\\\\textbf{Type IIIC} & \\\\mathbf{\\\\text{Open fracture with arterial injury needing repair}} & 25-50\\\\% & \\\\mathbf{\\\\text{Cefazolin + Gentamicin + Emergency Vascular Shunt}} \\\\\\\\\n\\\\hline\n\\\\end{array}$$\n\n---\n\n## 2. Mangled Extremity Severity Score (MESS) & Salvage Decision Matrix\n\n$$\\\\begin{array}{lcccc}\n\\\\hline\n\\\\textbf{Variable} & \\\\textbf{Clinical Criteria} & \\\\textbf{Score Points} \\\\\\\\\n\\\\hline\n\\\\textbf{1. Skeletal / Soft Tissue} & \\\\text{Low energy (stab, simple fx) / Medium (open fx, crush) / High (close-range GSW) / Massive} & 1 / 2 / 3 / 4 \\\\\\\\\n\\\\textbf{2. Limb Ischemia} & \\\\text{Pulse reduced / Absent pulse, capillary refill >3s / Cool, paralyzed, insensate (}\\\\times 2\\\\text{ if }>6\\\\text{h)} & 1 / 2 / 3 \\\\\\\\\n\\\\textbf{3. Shock} & \\\\text{Normotensive / Transient hypotension / Persistent hypotension in field} & 0 / 1 / 2 \\\\\\\\\n\\\\textbf{4. Age} & <30\\\\text{ years} / 30-50\\\\text{ years} / >50\\\\text{ years} & 0 / 1 / 2 \\\\\\\\\n\\\\hline\n\\\\end{array}$$\n\n- **MESS Score $\\ge 7$**: Highly predictive of **unsuccessful limb salvage and secondary amputation** (100% specificity for non-salvageable limb).","unitCode":"PG7.2","estimatedMinutes":180,"organ3dTarget":null}'::jsonb)
ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO content_blocks (id, lesson_id, type, order_index, metadata)
VALUES ('df028fb5-6548-4bc9-a056-ad0ff6b6bf50', '1abd02fa-b437-4c6e-a5f9-37d3ede48f7d', 'CLINICAL_CASE', 2, '{"scenario":"A 28-year-old motorcyclist is involved in a high-speed collision sustaining a severe open left tibia-fibula fracture with a 14 cm laceration over the anterior shin, extensive periosteal stripping with exposed cortical bone devoid of soft tissue coverage, and severe dirt/gravel contamination from the road. Distal pulses (dorsalis pedis and posterior tibial) are palpable with capillary refill under 2 seconds, and light touch sensation is intact across the foot.","question":"What is the Gustilo-Anderson classification, what is the appropriate empiric antibiotic regimen, and what soft-tissue reconstructive strategy will be required?","explanation":"This case illustrates an open tibia fracture with extensive soft-tissue loss: (1) Classification: Because the bone is stripped of periosteum and cannot be closed primarily, it is Type IIIB (Type IIIA has adequate local coverage, while Type IIIC mandates arterial repair); (2) Antibiotic Coverage: Type III open fractures require gram-positive (Cefazolin) plus gram-negative (Gentamicin) coverage, adding Penicillin G for soil/barnyard anaerobes; (3) Reconstruction: Staged debridement, spanning ex-fix, and definitive flap coverage are required."}'::jsonb)
ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
