VALUES ('4466dee8-6d1c-4059-ac52-6779f7778200', '4dc8f921-9f3b-4a2d-adfb-2492b4b13d03', 'Pelvic Ring Disruptions: Young-Burgess Patterns, Pelvic Binder & Preperitoneal Packing Protocols', 'PUBLISHED', 1)
