VALUES ('166af6b9-c154-4294-a1e0-4a51ac1bf5b8', 'd1d98b4b-56b8-4f76-a890-c27c4cf86de4', 'Acute Angle-Closure Glaucoma (AACG): Pupillary Block, Hyperosmotic Therapy & Laser Iridotomy Protocols', 'PUBLISHED', 1)
