VALUES ('4ca9c8bc-5258-4381-ae4f-116c97726734', '65d46cd9-74e0-45c3-a68d-dcbf93883bd6', 'Advanced Laryngeal & Hypopharyngeal Carcinoma: TNM Staging, Total Laryngectomy & Flap Reconstructions', 'PUBLISHED', 1)
