INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('8ad4f2a0-e56a-40e2-a53a-e9959605e25d', '3a1a1ba6-25a3-4af8-a2b0-2c8fbef25476', 'Endoscopic Sinus Surgery (FESS), Keros Skull Base Anatomy & Hadad Nasoseptal Flap CSF Repair', 'PUBLISHED', 1)
