VALUES ('26a00476-da31-4e2e-a2b8-c94bc980c495', '12806aef-a212-4c4e-a8f8-9eb2cedfdd93', 'Autonomic Pharmacology: Cholinergic, Adrenergic & Receptor Signal Transduction', 'PUBLISHED', 1)
