VALUES ('a559231d-9e8b-4425-afea-73c5e3dc5d88', '7b0f0f64-fc65-4d59-a747-47aae795c64b', 'Cardiac Cycle, Suga-Sagawa PV-Loops & Wiggers Mechanics', 'PUBLISHED', 1)
