VALUES ('b4df2af6-0e0a-4382-a9ba-01265adec0e2', '616f06a2-430e-407f-af51-bb3bd4fd6f28', 'Membrane Biophysics, Goldman-Hodgkin-Katz Potential & NMJ Mechanics', 'PUBLISHED', 1)
