INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('308076d6-d014-490f-a8d7-b942b93cddda', '237cdc2b-6357-4c44-aa98-0ae05418bcf8', 'PMR: Stroke Neuro-Rehabilitation, Brunnstrom Stages of Motor Recovery & Spasticity (MAS)', 'PUBLISHED', 1)
