VALUES ('f1c0df35-b05e-4641-a981-221c401e69b7', '263623b1-1c15-407b-aa8f-31b413e57c30', 'Pulmonology: Pulmonary Function Tests (PFTs), Spirometry & Flow-Volume Loops (Asthma vs COPD)', 'PUBLISHED', 1)
