INSERT INTO concepts (id, topic_id, title, sort_order)
VALUES ('dbf9f8c7-5a35-49eb-ab4d-9a650cde71fe', 'dd3abb95-a5cb-4c8e-af60-add3512718c1', 'ARDS Pathophysiology: Berlin Definition, ARDSNet Low Tidal Volume (4-8 mL/kg) & Prone Positioning', 1)
