VALUES ('747cb406-936b-4e98-a5ac-f6241bee80a1', '49ebe568-60f5-4113-a344-4682d6fcc8f0', 'Mechanisms of Hypoxemia, Alveolar Gas Equation, A-a Gradient & Capnography Waveforms', 'PUBLISHED', 1)
