INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('f9957fe6-b443-45fa-ab2c-f5af71b54ce7', 'e52c027b-4f76-42bb-a65a-a87e40aacc69', 'Mechanical Ventilation: Modes (VCV vs PCV), Pressures (PIP vs Pplat), Compliance & High PIP Troubleshooting', 'PUBLISHED', 1)
