INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('8b83b49d-d503-47d2-a1ea-c398108eeba1', '381cce23-bc7a-46d5-ad2c-de545c6d5fee', 'Radiology: Systematic Chest Radiography (RIPE & ABCDE), Silhouette Sign & Pneumothorax', 'PUBLISHED', 1)
