INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('1869c665-3cb5-4bf6-aef4-eaa3a7121191', '0f6d6e3f-f5f1-4189-ae46-204fc56070da', 'Acute Abdomen Emergency CT: Pneumoperitoneum (Rigler Sign), Mesenteric Ischemia & Diverticulitis', 'PUBLISHED', 1)
