VALUES ('308bba36-4ca6-4298-a6a8-eaac5932f002', '9f1bafea-30cb-4f4a-a57e-f62f519dbfeb', 'General Surgery: Acute Abdomen, Appendicitis Alvarado Score, Cholecystitis & Bowel Perforation', 'PUBLISHED', 1)
