VALUES ('4280fa4b-cb10-45a2-a35d-6d2d5151dff0', 'bb3a0f20-d79e-46ac-a0e0-356f40b0ca02', 'Burns & Critical Care: Wallace Rule of Nines, Parkland Fluid Resuscitation Formula & Escharotomy', 'PUBLISHED', 1)
