VALUES ('d69ac7e8-a456-40c0-a03b-1e19c2d0bb8a', 'b63cc63f-f67f-40d8-a0c4-9701dbfcf60f', 'Laparoscopic Cholecystectomy: The Critical View of Safety (CVS) & Bile Duct Injury Prevention', 'PUBLISHED', 1)
