INSERT INTO lessons (id, concept_id, title, status, version)
VALUES ('3e6e55b5-d5cf-4b43-a2a8-86ce5ac99ce1', '901fc689-207e-4bc4-aa89-52f8c4f9bf38', 'Toxic Alcohols (Methanol/Ethylene Glycol & Fomepizole), Envenomations & Enhanced Toxin Elimination', 'PUBLISHED', 1)
